import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"وقت کے پیچھے ہٹنے کے بنیادی اصول","description":"","frontmatter":{},"headers":[],"relativePath":"ur/82-时间回溯基本原则.md","filePath":"ur/82-时间回溯基本原则.md","lastUpdated":1789183869000}'),o={name:"ur/82-时间回溯基本原则.md"};function l(i,t,h,n,u,_){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="وقت-کے-پیچھے-ہٹنے-کے-بنیادی-اصول" tabindex="-1">وقت کے پیچھے ہٹنے کے بنیادی اصول <a class="header-anchor" href="#وقت-کے-پیچھے-ہٹنے-کے-بنیادی-اصول" aria-label="Permalink to &quot;وقت کے پیچھے ہٹنے کے بنیادی اصول&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>82</td></tr><tr><td>ماڈیول</td><td>بین السطح تعامل اور وقت کے اصول</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>وقت کے پیچھے ہٹنا، پہلے مشاہدہ پھر محدود مداخلت، ٹائم لائن استحکام، وجوہات کی تحفظ، اینکر اینکرنگ</td></tr></tbody></table><h2 id="_1-وقت-کے-پیچھے-ہٹنے-کی-تعریف-اور-حقیقت" tabindex="-1">1. وقت کے پیچھے ہٹنے کی تعریف اور حقیقت <a class="header-anchor" href="#_1-وقت-کے-پیچھے-ہٹنے-کی-تعریف-اور-حقیقت" aria-label="Permalink to &quot;1. وقت کے پیچھے ہٹنے کی تعریف اور حقیقت&quot;">​</a></h2><p>وقت کے پیچھے ہٹنے سے مراد اینکر قانون نیٹ ورک کی وقت کی جہت کی آپریٹنگ صلاحیت کے ذریعے، شعور، معلومات یا مادے کو ماضی کے وقت کے نوڈ پر واپس بھیجنے کا عمل ہے۔ ہینگ یوان ژو کے قانونی فریم ورک کے تحت، وقت یک طرفہ ناقابل واپسی لکیری بہاؤ نہیں ہے، بلکہ قانون نیٹ ورک میں ایک آپریٹیبل جہت ہے۔ تاہم، وقت کی جہت کے آپریشن میں انتہائی زیادہ خطرہ اور سخت پابندیاں ہیں، کوئی بھی وقت کے پیچھے ہٹنے کا عمل وجوہات کی زنجیر میں خلل، ٹائم لائن کی تقسیم اور یہاں تک کہ کائناتی سطح کے قانونی کمپن کا سبب بن سکتا ہے۔</p><p>وقت کے پیچھے ہٹنے کی حقیقت یہ ہے کہ &quot;قانون نیٹ ورک کی وقت کی جہت میں ایک پیچھے ہٹنے کا چینل بنانا، جس سے مخصوص معلومات یا توانائی چینل کے ساتھ الٹ پھیل سکے&quot;۔ اس عمل میں بہت زیادہ اینکر توانائی کی کھپت ہوتی ہے، اور جتنا زیادہ وقت پیچھے ہٹایا جائے، اتنا ہی پیچھے ہٹنے کا مواد پیچیدہ ہوگا، توانائی کی کھپت تیزی سے بڑھ جاتی ہے۔ فی الحال ہینگ یوان ژو کی تکنیکی صلاحیت صرف شعور اور معلومات کی سطح کے پیچھے ہٹنے کی حمایت کرتی ہے، مادے کی سطح کا مکمل پیچھے ہٹنا ابھی نظریاتی تحقیق کے مرحلے میں ہے۔</p><p>خاص طور پر اس بات پر زور دینے کی ضرورت ہے کہ وقت کے پیچھے ہٹنا &quot;ٹائم ٹریول&quot; کے برابر نہیں ہے۔ پیچھے ہٹنے والا مکمل مادی شکل میں ماضی میں داخل نہیں ہوتا، بلکہ شعور کے پروجیکشن یا معلومات کے پیکٹ کی شکل میں ہدف وقت کے نوڈ پر پہنچتا ہے۔ ماضی کے عرصے میں پیچھے ہٹنے والے کا وجود &quot;نیم شفاف&quot; ہے — مشاہدہ کر سکتا ہے، لیکن جسمانی تعامل کی صلاحیت سختی سے محدود ہے۔ یہ ڈیزائن خود وقت کے پیچھے ہٹنے کے حفاظتی طریقہ کار کا حصہ ہے۔</p><h2 id="_2-وقت-کے-پیچھے-ہٹنے-کے-سات-بنیادی-اصول" tabindex="-1">2. وقت کے پیچھے ہٹنے کے سات بنیادی اصول <a class="header-anchor" href="#_2-وقت-کے-پیچھے-ہٹنے-کے-سات-بنیادی-اصول" aria-label="Permalink to &quot;2. وقت کے پیچھے ہٹنے کے سات بنیادی اصول&quot;">​</a></h2><p>ہینگ یوان ژو کے وقت کے پیچھے ہٹنے کے آپریشن درج ذیل سات بنیادی اصولوں پر عمل کرتے ہیں، یہ اصول اینکر کونسل نے خصوصی قرارداد کی شکل میں قائم کیے ہیں، آئین کے بعد دوسرے نمبر پر قانونی طاقت رکھتے ہیں:</p><table tabindex="0"><thead><tr><th>اصول نمبر</th><th>اصول کا نام</th><th>بنیادی مواد</th></tr></thead><tbody><tr><td>پہلا اصول</td><td>پہلے مشاہدہ پھر محدود مداخلت</td><td>کوئی بھی پیچھے ہٹنا پہلے خالص مشاہدے کے مرحلے کو مکمل کرنا چاہیے، اور صرف اس بات کی تصدیق کے بعد کہ کوئی بڑا خطرہ نہیں ہے، محدود مداخلت کی جا سکتی ہے</td></tr><tr><td>دوسرا اصول</td><td>وجوہات کی تحفظ</td><td>پیچھے ہٹنے کا عمل پہلے سے ہونے والی بنیادی وجوہات کی زنجیر کو تبدیل نہیں کر سکتا، پیچھے ہٹنے سے پیدا ہونے والی وجوہات کی انحراف کو پیچھے ہٹنے کے خاتمے کے بعد درست کرنا ضروری ہے</td></tr><tr><td>تیسرا اصول</td><td>اینکر اینکرنگ</td><td>تمام پیچھے ہٹنے کے آپریشنز میں مستحکم اینکر کو وقت کے نقاط کے ماخذ کے طور پر لینا ضروری ہے، اینکر کے بغیر اندھے پیچھے ہٹنے کی ممانعت ہے</td></tr><tr><td>چوتھا اصول</td><td>کم سے کم اثر</td><td>پیچھے ہٹنے کے عمل میں تمام اعمال کم سے کم اثر کے اصول پر عمل کرنے چاہئیں، ماضی کی ٹائم لائن میں خلل کو زیادہ سے زیادہ کم کرنا چاہیے</td></tr><tr><td>پانچواں اصول</td><td>قابل ٹریس</td><td>ہر پیچھے ہٹنے میں مکمل آپریشن لاگ ریکارڈ کرنا ضروری ہے، جس میں پیچھے ہٹنے والے کی شناخت، ہدف وقت، مشاہدے کا مواد، مداخلت کے عمل اور وجوہات کی انحراف کی تشخیص شامل ہے</td></tr><tr><td>چھٹا اصول</td><td>پیراڈاکس کی ممانعت</td><td>وقت کے پیراڈاکس کا سبب بن سکنے والے کسی بھی آپریشن کی سختی سے ممانعت ہے، جس میں دادا کے قتل کا پیراڈاکس، معلومات کا پیراڈاکس اور وجودی پیراڈاکس شامل ہیں لیکن محدود نہیں</td></tr><tr><td>ساتواں اصول</td><td>بعد میں آڈٹ</td><td>پیچھے ہٹنے کے خاتمے کے بعد آزاد وقت قانون آڈٹ کمیٹی کے ذریعے بعد میں آڈٹ کرنا ضروری ہے، اس بات کی تصدیق کرنا کہ غیر کنٹرول شدہ ٹائم لائن میں خلل پیدا نہیں ہوا ہے</td></tr></tbody></table><p>سات اصولوں میں، &quot;پہلے مشاہدہ پھر محدود مداخلت&quot; سب سے بنیادی آپریٹو اصول ہے، باقی چھ اصول اس مرکز کے گرد گھومتے ہیں۔ اس اصول کے تفصیلی آپریشن اصول دستاویز 83 &quot;پہلے مشاہدہ پھر محدود مداخلت کے رہنما اصول&quot; میں دیکھے جا سکتے ہیں۔</p><h2 id="_3-وقت-کے-پیچھے-ہٹنے-کی-درجہ-بندی-کا-انتظام" tabindex="-1">3. وقت کے پیچھے ہٹنے کی درجہ بندی کا انتظام <a class="header-anchor" href="#_3-وقت-کے-پیچھے-ہٹنے-کی-درجہ-بندی-کا-انتظام" aria-label="Permalink to &quot;3. وقت کے پیچھے ہٹنے کی درجہ بندی کا انتظام&quot;">​</a></h2><p>پیچھے ہٹنے کے وقت کی حد اور مداخلت کی ڈگری کے مطابق، وقت کے پیچھے ہٹنے کے آپریشن کو تین انتظامی درجوں میں تقسیم کیا گیا ہے:</p><ol><li><p><strong>پہلے درجے کا پیچھے ہٹنا (قریبی وقت کا مشاہدہ)</strong>: پیچھے ہٹنے کی وقت کی حد اپنی سطح کے معیاری وقت کے 100 سال سے زیادہ نہیں ہے، اور صرف خالص مشاہدہ کیا جاتا ہے کوئی مداخلت نہیں کی جاتی ہے۔ سطح انتظامیہ بیورو کی منظوری، آپریشن کے عمل میں دو یا زیادہ وقت قانون نگران کی موجودگی میں نگرانی کی جائے گی۔</p></li><li><p><strong>دوسرے درجے کا پیچھے ہٹنا (دور وقت کا مشاہدہ)</strong>: پیچھے ہٹنے کی وقت کی حد 100 سال سے زیادہ لیکن 10000 سال سے زیادہ نہیں، یا پیچھے ہٹنے کے عمل میں انتہائی ہلکی مداخلت کی ضرورت ہے (جیسے ایک معلومات بھیجنا)۔ اینکر کونسل کے ماتحت وقت قانون کمیٹی کی منظوری لازمی ہے، اور تفصیلی وجوہات کی انحراف ہنگامی منصوبہ بندی کرنی ہوگی۔</p></li><li><p><strong>تیسرے درجے کا پیچھے ہٹنا (گہری مداخلت)</strong>: پیچھے ہٹنے کی وقت کی حد 10000 سال سے زیادہ، یا پیچھے ہٹنے کے عمل میں حقیقی مداخلت کی ضرورت ہے۔ اینکر کونسل کے مکمل اجلاس میں دو تہائی سے زیادہ اکثریت سے منظور ہونا چاہیے، اور سمبیوسس عدالت کے ذریعہ غیر آئینی جانچ کی جانی چاہیے، اس بات کی تصدیق کرنا کہ مداخلت کا عمل سمبیوسس آئین کے بنیادی اصولوں کے مطابق ہے۔</p></li></ol><p>کسی بھی درجے کے وقت کے پیچھے ہٹنے کو درج ذیل مقاصد کے لیے استعمال کرنے سے منع کیا گیا ہے: افراد یا چھوٹے گروہوں کے ذاتی فائدے کے لیے، ذاتی خواہشات کو پورا کرنے کے لیے تاریخی شخصیات کی تقدیر کو تبدیل کرنا، تہذیب کے ارتقاء کے قدرتی عمل کو بگاڑنا، اور کسی بھی شکل میں &quot;تاریخی ترمیم پسندی&quot; کا آپریشن۔</p><h2 id="_4-وقت-کے-پیچھے-ہٹنے-کی-توانائی-اور-تکنیکی-پابندیاں" tabindex="-1">4. وقت کے پیچھے ہٹنے کی توانائی اور تکنیکی پابندیاں <a class="header-anchor" href="#_4-وقت-کے-پیچھے-ہٹنے-کی-توانائی-اور-تکنیکی-پابندیاں" aria-label="Permalink to &quot;4. وقت کے پیچھے ہٹنے کی توانائی اور تکنیکی پابندیاں&quot;">​</a></h2><p>وقت کے پیچھے ہٹنے کی توانائی کی کھپت انتہائی زیادہ ہے۔ شعور کے پروجیکشن کے پیچھے ہٹنے کی مثال کے طور پر، 1 سال پیچھے ہٹنے کے لیے درکار توانائی تقریباً 10000 معیاری توانائی اکائیاں ہے، 100 سال پیچھے ہٹنے کے لیے تقریباً 1 ملین معیاری توانائی اکائیاں ہے، اور 10000 سال پیچھے ہٹنے کے لیے تقریباً 10 بلین معیاری توانائی اکائیاں درکار ہیں۔ توانائی کی کھپت اور پیچھے ہٹنے کی وقت کی حد کے درمیان تقریباً لوگارتھمک لکیری تعلق ہے، لیکن اہم تاریخی نوڈز کو عبور کرتے وقت توانائی کی چوٹی دیکھی جاتی ہے — اس کی وجہ یہ ہے کہ اہم تاریخی نوڈز پر وجوہات کی زنجیر کی کثافت انتہائی زیادہ ہے، اور پیچھے ہٹنے کے آپریشن کو زیادہ وجوہاتی جڑت پر قابو پانا پڑتا ہے۔</p><p>تکنیکی سطح پر، وقت کے پیچھے ہٹنے کے لیے &quot;وقت قانون اینکرنگ ڈیوائس&quot; اور &quot;شعور پروجیکشن ٹرانسمیشن سرنی&quot; کے باہمی کام کی ضرورت ہوتی ہے۔ پہلا ہدف وقت کے نوڈ پر مستحکم وقت کے نقاط قائم کرنے کے لیے ذمہ دار ہے، دوسرا پیچھے ہٹنے والے کے شعور کے پروجیکشن کو محفوظ طریقے سے پہنچانے اور ماضی کے عرصے میں اس کے وجود کو برقرار رکھنے کے لیے ذمہ دار ہے۔ تمام پیچھے ہٹنے کے آلات کو اینکر نگرانی کمیٹی کے سیکیورٹی سرٹیفیکیشن سے گزرنا چاہیے، غیر سرٹیفائیڈ خود ساختہ آلات کا استعمال کرتے ہوئے پیچھے ہٹنے کے آپریشن کی ممانعت ہے۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>وقت کے پیچھے ہٹنا ہینگ یوان ژو کی سب سے طاقتور اور سب سے خطرناک قانونی آپریٹنگ صلاحیتوں میں سے ایک ہے۔ سات بنیادی اصول اور درجہ بندی کا انتظامی نظام مل کر وقت کے پیچھے ہٹنے کا حفاظتی فریم ورک تشکیل دیتے ہیں، جس کی بنیادی روح ہے &quot;وجوہات کے لیے تعظیم، احتیاط کے ساتھ آپریشن&quot;۔ وقت کے پیچھے ہٹنے کا جائز استعمال صرف آثار قدیمہ کی تحقیق، تاریخی حقیقت کی بحالی اور ناپید ہونے کے درجے کے بحران کی ابتدائی انتباہ تک محدود ہے، اس دائرے سے باہر کوئی بھی استعمال کائنات کے قوانین کی توہین سمجھا جائے گا۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>83-پہلے مشاہدہ پھر محدود مداخلت کے رہنما اصول</li><li>89-وقت کے پیراڈاکس روک تھام کا طریقہ کار</li><li>84-آثار قدیمہ پروٹوکول کا عمومی خاکہ</li></ul>',21)])])}const q=a(o,[["render",l]]);export{s as __pageData,q as default};
